using MediatR;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Vitarish.Communications.Application.Abstractions;
using Vitarish.Communications.Application.Commands;
using Vitarish.Communications.Application.Queries;
using Vitarish.Communications.Contracts.Errors;
using Vitarish.Communications.Contracts.Requests;
using Vitarish.Communications.Contracts.Responses;
using Vitarish.Communications.Contracts.Results;
using Vitarish.Communications.Contracts.Routes;
using Vitarish.Modules.Base.Core.Endpoints;
using C = Vitarish.Communications.Contracts.Reminders;
using D = Vitarish.Communications.Domain.Dto;
using DE = Vitarish.Communications.Domain.Enums;
using M = Vitarish.Communications.Domain.Models;
namespace Vitarish.Communications.Api;
public static class CommunicationsApiEndpointMapping
{
    public static IEndpointRouteBuilder MapCommunicationsApi(this IEndpointRouteBuilder endpoints){ RouteGroupBuilder group=endpoints.MapProtectedModuleGroup(CommunicationsApiRoutes.Base).WithTags("Communications"); _=group.MapModulePost(CommunicationsApiRoutes.SendEmail, SendEmailAsync, "CommunicationsSendEmail"); _=group.MapModulePost(CommunicationsApiRoutes.SendSms, SendSmsAsync, "CommunicationsSendSms"); _=group.MapModulePost(CommunicationsApiRoutes.SendSmsCode, SendSmsCodeAsync, "CommunicationsSendSmsCode"); _=group.MapModulePost(CommunicationsApiRoutes.SendSmsReminder, SendSmsReminderAsync, "CommunicationsSendSmsReminder"); _=group.MapModuleGet(CommunicationsApiRoutes.SmsDeliveryState, GetSmsDeliveryStateAsync, "CommunicationsGetSmsDeliveryState"); _=group.MapModulePost(CommunicationsApiRoutes.RemindersQuery, ListRemindersAsync, "CommunicationsListReminders"); _=group.MapModulePost(CommunicationsApiRoutes.Reminders, CreateReminderAsync, "CommunicationsCreateReminder"); _=group.MapModulePost(CommunicationsApiRoutes.ReminderRange, CreateReminderRangeAsync, "CommunicationsCreateReminderRange"); _=group.MapModuleGet(CommunicationsApiRoutes.RemindersBySource, GetRemindersBySourceAsync, "CommunicationsGetRemindersBySource"); _=group.MapModulePut(CommunicationsApiRoutes.ReminderById, UpdateReminderAsync, "CommunicationsUpdateReminder"); _=group.MapModuleDelete(CommunicationsApiRoutes.ReminderById, DeleteReminderAsync, "CommunicationsDeleteReminder"); _=group.MapModulePost(CommunicationsApiRoutes.MarkReminderSent, MarkReminderSentAsync, "CommunicationsMarkReminderSent"); return endpoints; }
    private static async Task<IResult> SendEmailAsync(SendEmailRequest r, IMessagesService s, CancellationToken ct){ try{ await SendEmail.ExecuteAsync(s,new M.Message{Recipient=r.Recipient,Subject=r.Subject,Body=r.TextBody,HtmlBody=r.HtmlBody},ct); return Results.Accepted(value:CommunicationsCommandResult.Accepted()); } catch(Exception ex){ return MapCommandException(ex); } }
    private static async Task<IResult> SendSmsAsync(SendSmsRequest r, IMessagesService s, CancellationToken ct){ try{ M.SmsSendResult sent=await SendSms.ExecuteAsync(s,new M.Message{Recipient=r.Recipient,Body=r.Body},ct); return Results.Accepted(value:CommunicationsCommandResult.Accepted(sent.MessageId)); } catch(Exception ex){ return MapCommandException(ex); } }
    private static async Task<IResult> SendSmsCodeAsync(SendSmsCodeRequest r, IMessagesService s, CancellationToken ct){ try{ await SendSmsCode.ExecuteAsync(s,new M.Message{Recipient=r.Recipient,Body=r.Code},ct); return Results.Accepted(value:CommunicationsCommandResult.Accepted()); } catch(Exception ex){ return MapCommandException(ex); } }
    private static IResult SendSmsReminderAsync(SendSmsReminderRequest r, ICommunicationCommandQueue q){ q.Enqueue(new SmsReminderCommunicationCommand(r.Recipient,r.Project,r.Procedure,r.Event,r.Tenant)); return Results.Accepted(value:CommunicationsCommandResult.Queued()); }
    private static async Task<IResult> GetSmsDeliveryStateAsync(long messageId, IMessagesService s, CancellationToken ct){ try{ M.SmsDeliveryState state=await GetSmsDeliveryState.ExecuteAsync(s,messageId,ct); _=long.TryParse(state.MessageId,out long id); return Results.Ok(new SmsDeliveryStateResponse(id,state.Status,state.MessageText,DateTimeOffset.UtcNow)); } catch(ArgumentException ex){ return Results.BadRequest(new CommunicationsError(CommunicationsErrorCode.ValidationFailure, ex.Message)); } }
    private static async Task<IResult> ListRemindersAsync(C.ReminderDescriptorDto d, IRemindersService s, CancellationToken ct)=>Results.Ok((await s.GetListAsync(new D.ReminderDescriptorDto{SourceId=d.SourceId,IsSent=d.IsSent},ct).GetValueOrDefaultAsync() ?? []).Select(ToContract).ToList());
    private static async Task<IResult> CreateReminderAsync(C.ReminderWriteDto r, IRemindersService s, CancellationToken ct){ D.ReminderReadDto? dto=await s.AddAsync(ToDomain(r),ct).GetValueOrDefaultAsync(); return dto is null?Results.BadRequest(new CommunicationsError(CommunicationsErrorCode.ValidationFailure,"Reminder could not be created.")):Results.Ok(ToContract(dto)); }
    private static async Task<IResult> CreateReminderRangeAsync(C.ReminderRangeCreateRequest r, IRemindersService s, CancellationToken ct)=>Results.Ok((await s.AddRangeAsync(r.SourceId,r.Recipients.Select(ToDomain).ToList(),r.Subject,r.TextBody,r.RemindAt,ct)).Select(ToContract).ToList());
    private static async Task<IResult> GetRemindersBySourceAsync(Guid sourceId, IRemindersService s, CancellationToken ct)=>Results.Ok((await s.GetBySourceAsync(sourceId,ct)).Select(ToContract).ToList());
    private static async Task<IResult> UpdateReminderAsync(Guid id, C.ReminderUpdateRequest r, IRemindersService s, CancellationToken ct){ if(id!=r.Id) return Results.BadRequest(new CommunicationsError(CommunicationsErrorCode.ValidationFailure,"Route id must match request id.")); D.ReminderReadDto? dto=await s.UpdateAsync(id,(DE.ReminderKind)r.Kind,r.RecipientUserId,r.Recipient,r.Subject,r.TextBody,r.RemindAt,ct); return dto is null?Results.NotFound(new CommunicationsError(CommunicationsErrorCode.NotFound,"Reminder was not found.")):Results.Ok(ToContract(dto)); }
    private static async Task<IResult> DeleteReminderAsync(Guid id, IRemindersService s, CancellationToken ct){ _=await s.RemoveAsync(id,ct); return Results.Ok(CommunicationsCommandResult.Accepted()); }
    private static async Task<IResult> MarkReminderSentAsync(Guid id, C.MarkReminderSentRequest r, ISender sender, CancellationToken ct){ await sender.Send(new MarkReminderSentCommand(id,r.SentAt),ct); return Results.Ok(CommunicationsCommandResult.Accepted()); }
    private static IResult MapCommandException(Exception ex)=> ex switch { OperationCanceledException=>Results.StatusCode(StatusCodes.Status499ClientClosedRequest), ArgumentException=>Results.BadRequest(CommunicationsCommandResult.Failed(CommunicationsCommandStatus.ValidationFailure,new(CommunicationsErrorCode.ValidationFailure,ex.Message))), TimeoutException=>Results.StatusCode(StatusCodes.Status504GatewayTimeout), _=>Results.Problem(ex.Message) };
    private static D.ReminderWriteDto ToDomain(C.ReminderWriteDto r)=>new(r.SourceId,(DE.ReminderKind)r.Kind,r.RecipientUserId,r.Recipient??string.Empty,r.Subject??string.Empty,r.TextBody??string.Empty,r.RemindAt,r.SentAt,r.IsSent);
    private static D.ReminderRecipientReadDto ToDomain(C.ReminderRecipientReadDto r)=>new(){Kind=(DE.ReminderKind)r.Kind,RecipientUserId=r.RecipientUserId,Recipient=r.Recipient??string.Empty};
    private static C.ReminderReadDto ToContract(D.ReminderReadDto r)=>new(r.Id,r.SourceId,(C.ReminderKind)r.Kind,r.RecipientUserId,r.Recipient,r.Subject,r.TextBody,r.RemindAt,r.SentAt,r.IsSent,r.CreatedBy,r.CreatedAt);
}
